def build_layout(fib, cuts):
    """Canonical node layout.  fib: list of (addr, length, hop).

    Returns (stages, used) where stages[i] is a list of
    (node_addr, tuple_of_rules, tuple_of_edges); a rule is (addr, len, hop)
    sorted by (len, addr) and an edge is (addr, child_index) sorted by addr.
    """
    S = len(cuts) - 1
    fs = sorted(fib, key=lambda p: (p[0], p[1]))
    zero_rule = None
    for p in fs:
        if p[1] == 0:
            zero_rule = p
            break
    node_lists = []
    for i in range(S + 1):
        d = cuts[i]
        if i == 0:
            node_lists.append([0])
            continue
        lst = []
        if d < 128:
            m = TMASK[d]
            prev = None
            for p in fs:
                if p[1] <= d:
                    continue
                k = p[0] & m
                if k != prev:
                    lst.append(k)
                    prev = k
        node_lists.append(lst)
    stages = []
    used = []
    for i in range(S):
        b = cuts[i]
        e = cuts[i + 1]
        nl = node_lists[i]
        nmap = {}
        ew = 0
        if e < 128:
            nmap = {v: j for j, v in enumerate(node_lists[i + 1])}
            ew = 32 + align8(e - b)
        mb = TMASK[b]
        me = TMASK[e]
        groups = []
        prevk = None
        for p in fs:
            if p[1] <= b:
                continue
            k = p[0] & mb
            if k != prevk:
                groups.append((k, [p]))
                prevk = k
            else:
                groups[-1][1].append(p)
        nodes = []
        tot = 0
        for j in range(len(nl)):
            na = nl[j]
            grp = groups[j][1] if j < len(groups) else ()
            rules = []
            cost = 128
            edges = []
            prevk = None
            for p in grp:
                l = p[1]
                if l <= e:
                    rules.append(p)
                    cost += 32 + align8(l - b)
                elif e < 128:
                    k = p[0] & me
                    if k != prevk:
                        edges.append((k, nmap[k]))
                        prevk = k
                        cost += ew
            if i == 0 and zero_rule is not None:
                rules.append(zero_rule)
                cost += 32
            if len(rules) > 1:
                rules.sort(key=lambda p: (p[1], p[0]))
            nodes.append((na, tuple(rules), tuple(edges)))
            tot += align64(cost)
        stages.append(nodes)
        used.append(tot)
    return stages, used


def peak_of(used, caps):
    bn, bd = 0, 1
    for u, c in zip(used, caps):
        if u * bd > bn * c:
            bn, bd = u, c
    g = math.gcd(bn, bd)
    if g == 0:
        g = 1
    return bn // g, bd // g


def image_to_json(caps, ms, cuts, stages, used, peak):
    out_stages = []
    S = len(cuts) - 1
    for i in range(S):
        b = cuts[i]
        e = cuts[i + 1]
        nodes = []
        for (na, rules, edges) in stages[i]:
            nodes.append({
                'prefix': canon_prefix(na, b),
                'rules': [{'prefix': canon_prefix(a, l), 'hop': h}
                          for (a, l, h) in rules],
                'edges': [{'prefix': canon_prefix(a, e), 'child': c}
                          for (a, c) in edges],
            })
        out_stages.append({'nodes': nodes})
    return {
        'status': 'ok',
        'capacities': list(caps),
        'max_stride': ms,
        'cuts': list(cuts),
        'stages': out_stages,
        'used_bits': list(used),
        'peak': {'num': peak[0], 'den': peak[1]},
    }


